package com.example.demo.controller;

import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/users")
public class UserNegotiationController {

    @GetMapping(value = "/{id}", produces = { MediaType.APPLICATION_JSON_VALUE, MediaType.APPLICATION_XML_VALUE })
    public ResponseEntity<UserDto> getUser(@PathVariable Long id) {
        UserDto user = new UserDto(id, "Jane Doe", "jane.doe@example.com");
        // Spring MVC automatically selects Jackson (JSON) or JAXB (XML) 
        // based on the incoming HTTP Accept header.
        return ResponseEntity.ok(user);
    }
}

record UserDto(Long id, String name, String email) {}
